SELECT CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, MAX(credit_limit) - MIN(credit_limit) AS credit_limit_range, AVG(credit_limit) AS avg_credit_limit FROM customers WHERE credit_limit > 11300 AND email NOT LIKE '%@startup.io' GROUP BY CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY avg_credit_limit DESC;
